import unittest
from candidate import will_it_fly

class TestWillItFly(unittest.TestCase):
    def test_will_it_fly_balanced_and_light(self):
        self.assertTrue(will_it_fly([3, 2, 3], 9))

    def test_will_it_fly_unbalanced_but_light(self):
        self.assertFalse(will_it_fly([1, 2], 5))

    def test_will_it_fly_balanced_but_heavy(self):
        self.assertFalse(will_it_fly([3, 2, 3], 1))

    def test_will_it_fly_single_element(self):
        self.assertTrue(will_it_fly([3], 5))

    def test_will_it_fly_empty_list(self):
        self.assertTrue(will_it_fly([], 5))

    def test_will_it_fly_none_input(self):
        with self.assertRaises(TypeError):
            will_it_fly(None, 5)

    def test_will_it_fly_non_list_input(self):
        with self.assertRaises(TypeError):
            will_it_fly('abc', 5)

    def test_will_it_fly_non_numeric_elements(self):
        with self.assertRaises(TypeError):
            will_it_fly([1, 'a', 1], 5)

    def test_will_it_fly_negative_weight(self):
        with self.assertRaises(ValueError):
            will_it_fly([1, 2, 1], -5)

    def test_will_it_fly_zero_weight(self):
        self.assertFalse(will_it_fly([1, 2, 1], 0))

if __name__ == '__main__':
    unittest.main()
